#!/bin/sh
# build.sh - build the generated Word document for docs/docsDocxView.
#
# combined.md, _manifest.json, and _meta.json are generated by the
# docs-docx-view skill. If docs/toc.yml, CONTEXT.md, or the module set changed,
# re-run that skill first so combined.md is fresh.
#
# This helper is build-only: it never generates content, never validates the
# sources, never installs packages, and never looks for the skill directory.
# It is yours to edit; docs-docx-view will not overwrite it.
set -eu

cd "$(dirname "$0")"

if [ "$#" -gt 1 ]; then
    echo "usage: $0 [--clean]" >&2
    exit 2
fi

clean=0
case "${1:-}" in
    "") ;;
    --clean) clean=1 ;;
    *)
        echo "usage: $0 [--clean]" >&2
        exit 2
        ;;
esac

if [ "$clean" -eq 1 ]; then
    rm -rf build
fi

PY="${DOCS_PY:-../../.venv-docs/bin/python}"

if [ ! -x "$PY" ]; then
    echo "error: render env not found at $PY; run the docs-docx-view skill first." >&2
    exit 1
fi

for name in combined.md _meta.json _manifest.json reference.docx; do
    if [ ! -f "$name" ]; then
        echo "error: $name is missing; run the docs-docx-view skill first." >&2
        exit 1
    fi
done

OUT=$("$PY" -c 'import json;print(json.load(open("_meta.json"))["output"])' 2>/dev/null) || {
    echo "error: cannot read output path from _meta.json; run the docs-docx-view skill first." >&2
    exit 1
}

PANDOC=$("$PY" -c 'import pypandoc;print(pypandoc.get_pandoc_path())' 2>/dev/null) || {
    echo "error: pypandoc is not installed in $PY; run the docs-docx-view skill first." >&2
    exit 1
}

mkdir -p build

echo "\"$PANDOC\" --from=markdown+raw_attribute --to=docx --reference-doc=reference.docx --resource-path=\"$(cd ../.. && pwd)\" -o \"$OUT\" combined.md"

set +e
"$PANDOC" --from=markdown+raw_attribute --to=docx --reference-doc=reference.docx --resource-path="$(cd ../.. && pwd)" -o "$OUT" combined.md 2> build/pandoc.log
rc=$?
set -e

if [ "$rc" -ne 0 ]; then
    echo "error: pandoc failed (exit $rc); build/ may contain stale or partial output." >&2
    echo "log: $(pwd)/build/pandoc.log" >&2
    exit "$rc"
fi

if [ ! -f "$OUT" ]; then
    echo "error: expected output $OUT was not created; see $(pwd)/build/pandoc.log" >&2
    exit 1
fi

messages=0
if [ -f build/pandoc.log ]; then
    messages=$(wc -l < build/pandoc.log | tr -d ' ')
fi
size=$(wc -c < "$OUT" | tr -d ' ')

echo "Messages: $messages ($(pwd)/build/pandoc.log)"
echo "Output:   $(pwd)/$OUT"
echo "Size:     $size bytes"
